                {
                    "commentary_id": 44994865,
                    "inning": 1,
                    "type": 1,
                    "data": {
                        "overs": "0.6",
                        "wicket": "",
                        "runs": "3",
                        "title": "Shaheen Shah Afridi to Khawaja",
                        "description": "Haring in and bangs it into the pitch on slightly shorter length, slightly leg-sidish and whipped away wristily in front of midwicket for three runs, long chase for the fielder in the deep"
                    }
                },
                {
                    "commentary_id": 44994862,
                    "inning": 1,
                    "type": 1,
                    "data": {
                        "overs": "0.5",
                        "wicket": "",
                        "runs": "4",
                        "title": "Shaheen Shah Afridi to Khawaja",
                        "description": "Crikey! Shaheen has found his radar! Bowls a jaffa at a hard length and it kicks and screams off the deck, pegs Khawaja back who hops and awkwardly dabs it into the slip cordon but once again he's lucky it didn't get stuck into the hands and skittles away to the rope. Fortuitous but they all count"
                    }
                },
                {
                    "commentary_id": 44994860,
                    "inning": 1,
                    "type": 1,
                    "data": {
                        "overs": "0.4",
                        "wicket": "",
                        "runs": "4",
                        "title": "Shaheen Shah Afridi to Khawaja",
                        "description": "A touch short on a nagging off stump line, he had to play at it, he pokes it away with soft hands and the ball dribbles away between second and third slip to third man boundary, played it very late"
                    }
                },
                {
                    "commentary_id": 44994858,
                    "inning": 1,
                    "type": 1,
                    "data": {
                        "overs": "0.3",
                        "wicket": "",
                        "runs": "1",
                        "title": "Shaheen Shah Afridi to Warner",
                        "description": "Good length and came back a shade from outside off, he props forward and punches it to Shan Masood at short cover who fumbles"
                    }
                },
                {
                    "commentary_id": 44994856,
                    "inning": 1,
                    "type": 1,
                    "data": {
                        "overs": "0.2",
                        "wicket": "",
                        "runs": "1",
                        "title": "Shaheen Shah Afridi to Khawaja",
                        "description": "Back of a length, slanting it in from outside off, again a bit too straight and he flicks it away using his fluid wrists behind square"
                    }
                },
                {
                    "commentary_id": 44994855,
                    "inning": 1,
                    "type": 1,
                    "data": {
                        "overs": "0.1",
                        "wicket": "",
                        "runs": "1",
                        "title": "Shaheen Shah Afridi to Warner",
                        "description": ""
                    }
                }
