                        "wicket": "",
                        "runs": "4",
                        "title": "Khurram Shahzad to Head",
                        "description": "Short, wide and punished! Unleashed a cracking cut, not afraid of the fierce bounce, he sees the width and latches onto it in a jiffy. Absolutely cracked past cover-point"
