                    "type": 1,
                    "data": {
                        "overs": "2.3",
                        "wicket": "",
                        "runs": "4",
                        "title": "Shaheen Shah Afridi to Warner",
                        "description": "Slams it into the deck and gets a lot of purchase off the deck, he is firmly rooted back in crease and jumps to get away from it, connects and it just goes past the third slip and runs away to the fence. A testing delivery. Zinger from Shaheen!"
                    }
