                        "title": "Shaheen Shah Afridi to Khawaja",
                        "description": "Crikey! Shaheen has found his radar! Bowls a jaffa at a hard length and it kicks and screams off the deck, pegs Khawaja back who hops and awkwardly dabs it into the slip cordon but once again he's lucky it didn't get stuck into the hands and skittles away to the rope. Fortuitous but they all count"
